TEST_F(SpBmpTest, Write_8bppRgb222Rle8_GivenAbsoluteMode) {
    // Create 5 different pixels in a row to trigger absolute mode
    SpColourArgb pixels[5];
    for (int i = 0; i < 5; ++i) {
        pixels[i] = RGBA_FROM_ARRAY(rgb222_colour_table[i]);  // Colors 0 - 4
    }

    TestSurface surface = { pixels, 5, 1 };
    char bmp_data[512] = { 0 };
    SafeBuffer file;
    safe_buffer_init(&file, bmp_data, sizeof(bmp_data));

    EXPECT_EQ(kSpBmpOk, spbmp_write(&file, kSpBmp8bppRgb222Rle8, &surface, 0, 0, 5, 1));

    int offset = 310;  // After header and palette

    // Expected for 5 different pixels:
    // 00 05 00 01 02 03 04 00  (absolute mode: 5 pixels, then padding byte)
    // 00 00                    (end of line)
    // 00 01                    (end of bitmap)

    EXPECT_EQ(0x00, static_cast<uint8_t>(bmp_data[offset]));     // Escape
    EXPECT_EQ(0x05, static_cast<uint8_t>(bmp_data[offset + 1])); // Count = 5
    EXPECT_EQ(0x00, static_cast<uint8_t>(bmp_data[offset + 2])); // Pixel 0
    EXPECT_EQ(0x01, static_cast<uint8_t>(bmp_data[offset + 3])); // Pixel 1
    EXPECT_EQ(0x02, static_cast<uint8_t>(bmp_data[offset + 4])); // Pixel 2
    EXPECT_EQ(0x03, static_cast<uint8_t>(bmp_data[offset + 5])); // Pixel 3
    EXPECT_EQ(0x04, static_cast<uint8_t>(bmp_data[offset + 6])); // Pixel 4
    EXPECT_EQ(0x00, static_cast<uint8_t>(bmp_data[offset + 7])); // Padding
}

