TEST_F(SpBmpTest, Write_16bpp_Rgb555) {
    SpColourArgb pixels[2];
    pixels[0] = RGBA(0x00, 0x00, 0xFF, 0xFF); // Blue
    pixels[1] = RGBA(0xFF, 0xFF, 0xFF, 0xFF); // White

    TestSurface surface = { pixels, 2, 1 };
    char bmp_data[128] = { 0 };
    SafeBuffer file;
    safe_buffer_init(&file, bmp_data, sizeof(bmp_data));

    EXPECT_EQ(kSpBmpOk, spbmp_write(&file, kSpBmp16bppRgb555, &surface, 0, 0, 2, 1));

    // Pixel 0 (Blue): 0 00000 00000 11111 -> 0x001F
    // Little Endian: 0x1F, 0x00
    EXPECT_EQ(0x1F, static_cast<uint8_t>(bmp_data[54]));
    EXPECT_EQ(0x00, static_cast<uint8_t>(bmp_data[55]));

    // Pixel 1 (White): 0 11111 11111 11111 -> 0x7FFF
    // Little Endian: 0xFF, 0x7F
    EXPECT_EQ(0xFF, static_cast<uint8_t>(bmp_data[56]));
    EXPECT_EQ(0x7F, static_cast<uint8_t>(bmp_data[57]));
}

TEST_F(SpBmpTest, Write_16bpp_Rgb565) {
    // 2x1 Image: Pixel 0 is Pure Red, Pixel 1 is Pure Green
    SpColourArgb pixels[2];
    pixels[0] = RGBA(0xFF, 0x00, 0x00, 0xFF); // Red
    pixels[1] = RGBA(0x00, 0xFF, 0x00, 0xFF); // Green

    TestSurface surface = { pixels, 2, 1 };
    char bmp_data[128] = { 0 };
    SafeBuffer file;
    safe_buffer_init(&file, bmp_data, sizeof(bmp_data));

    EXPECT_EQ(kSpBmpOk, spbmp_write(&file, kSpBmp16bppRgb565, &surface, 0, 0, 2, 1));

    // 1. Header Verification
    EXPECT_EQ(16, *reinterpret_cast<uint16_t*>(&bmp_data[28])); // 16 bpp
    // Compression for 565 is usually BI_BITFIELDS (3), but check your impl.
    // If you use standard BI_RGB (0), most viewers assume 555.

    // 2. Pixel Data Verification (Offset 66)
    // Pixel 0 (Red): 11111 000000 00000 -> 0xF800
    // Little Endian: 0x00, 0xF8
    EXPECT_EQ(0x00, static_cast<uint8_t>(bmp_data[66]));
    EXPECT_EQ(0xF8, static_cast<uint8_t>(bmp_data[67]));

    // Pixel 1 (Green): 00000 111111 00000 -> 0x07E0
    // Little Endian: 0xE0, 0x07
    EXPECT_EQ(0xE0, static_cast<uint8_t>(bmp_data[68]));
    EXPECT_EQ(0x07, static_cast<uint8_t>(bmp_data[69]));

    // 3. Row Padding
    // 2 pixels * 2 bytes = 4 bytes. 4 is a multiple of 4, so no padding bytes.
}

